const questions=[{title:'1. Entenda antes de registrar',scene:'Uma pessoa informa: “Não consigo acessar o portal e tenho uma entrega hoje”. Qual é a melhor primeira resposta?',options:['Solicitar a senha para testar o acesso.','Perguntar a mensagem de erro, quando começou e qual atividade foi impedida.','Encaminhar imediatamente sem registrar informações.'],answer:1,feedback:'Uma investigação breve reúne contexto e impacto. Nunca solicite a senha. O registro deve conter informações úteis para quem dará continuidade.'},{title:'2. Registre o que permite agir',scene:'Você identificou a mensagem de erro e confirmou que o problema começou nesta manhã. O que deve constar no registro?',options:['Somente “portal com problema”, para ganhar tempo.','Captura da tela com senha e dados pessoais desnecessários.','Descrição, mensagem de erro, início, impacto e identificador autorizado para retorno.'],answer:2,feedback:'Um registro claro reúne descrição, evidências necessárias, momento e impacto. Evite dados sensíveis que não são necessários ao atendimento.'},{title:'3. Defina a prioridade com critérios',scene:'O problema impede uma pessoa de acessar um recurso. Ainda não sabemos se outras pessoas foram afetadas. Como definir a prioridade?',options:['Confirmar abrangência e prazo antes de aplicar a matriz de impacto e urgência.','Classificar sempre como crítico porque há uma entrega hoje.','Usar a ordem de chegada sem avaliar impacto.'],answer:0,feedback:'Urgência e impacto são critérios diferentes. Investigue abrangência e prazo e aplique a matriz definida pela organização. Este exemplo não substitui regras de um serviço real.'},{title:'4. Encaminhe e feche o ciclo',scene:'O chamado será encaminhado para a equipe responsável. Qual mensagem ajuda a pessoa a acompanhar o atendimento?',options:['“Encaminhado. Aguarde.”','Informar protocolo, equipe responsável, próximo passo e previsão de atualização acordada.','Prometer solução imediata sem confirmação da equipe.'],answer:1,feedback:'Transparência exige referência, responsabilidade e próximo passo. Combine uma atualização possível, sem prometer um prazo de solução que não foi validado.'}];
let lessonState=FormaScorm.load()||{step:-1,answers:[],finished:false};if(!Number.isInteger(lessonState.step)||lessonState.step< -1||lessonState.step>4||!Array.isArray(lessonState.answers)||lessonState.answers.length>4||lessonState.answers.some(a=>!a||!Number.isInteger(a.choice)||a.choice<0||a.choice>2)){lessonState={step:-1,answers:[],finished:false}}lessonState.answers=lessonState.answers.map((a,i)=>({choice:a.choice,correct:a.choice===questions[i].answer}));lessonState.step=Math.min(lessonState.step,lessonState.answers.length);lessonState.finished=lessonState.answers.length===4&&lessonState.step===4;let selected=null;const lesson=document.getElementById('lesson');const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));if(window.FORMA_SCORM_VERSION!=='demo')document.getElementById('portfolioLink').removeAttribute('href');
function saveLesson(){const ok=FormaScorm.save(lessonState);document.getElementById('connection').textContent=FormaScorm.mode+(ok?'':' · progresso não confirmado')}
function drawLesson(focus=false){document.getElementById('connection').textContent=FormaScorm.mode;document.getElementById('progress').style.width=(lessonState.finished?100:Math.max(0,lessonState.step)/4*100)+'%';document.querySelector('.track').setAttribute('aria-valuenow',String(parseFloat(document.getElementById('progress').style.width)));if(lessonState.step===-1){lesson.innerHTML='<h2 tabindex="-1">Sua missão: um atendimento que continua bem.</h2><p>Na empresa fictícia Aurora, um registro incompleto pode gerar novas perguntas e atrasar o encaminhamento. Você vai tomar quatro decisões e receber feedback após cada uma.</p><div class="chips"><span>4 decisões</span><span>25 pontos por decisão</span><span>Aprovação: 75 pontos</span></div><p>Ao final, você deverá identificar os dados necessários, aplicar critérios de prioridade e comunicar o próximo passo. A avaliação usa a primeira resposta confirmada de cada decisão.</p><button class="primary" data-course="start">Começar experiência</button>'}else if(lessonState.finished){const score=lessonState.answers.filter(a=>a.correct).length*25;lesson.innerHTML=`<h2 tabindex="-1">${score>=75?'Missão concluída.':'Experiência concluída. Revise e pratique.'}</h2><div class="score">${score}<small> / 100</small></div><p>${score>=75?'Você atingiu o critério de aprovação deste exemplo.':'A aprovação exige 75 pontos. Os feedbacks ajudam a identificar o que revisar.'}</p><div class="feedback">${lessonState.answers.map((a,i)=>`<p><b>Decisão ${i+1}: ${a.correct?'correta':'revisar'}</b><br>${questions[i].feedback}</p>`).join('')}</div><p>Próximo passo no trabalho: use o guia e peça uma observação com critérios. A nota do curso não comprova, sozinha, aplicação no trabalho.</p>${window.FORMA_SCORM_VERSION==='demo'?'<button data-course="restart">Praticar novamente</button>':'<p>Para uma nova tentativa avaliada, utilize o recurso de tentativas do LMS.</p>'}`}else{const q=questions[lessonState.step],answered=lessonState.answers[lessonState.step];lesson.innerHTML=`<span class="tag">DECISÃO ${lessonState.step+1} DE 4</span><h2 tabindex="-1">${q.title}</h2><p>${q.scene}</p><div class="options" role="group" aria-label="Escolha uma resposta">${q.options.map((o,i)=>`<button class="option" data-choice="${i}" aria-pressed="${answered?answered.choice===i:selected===i}" ${answered?'disabled':''}>${String.fromCharCode(65+i)}. ${o}</button>`).join('')}</div>${answered?`<div class="feedback" role="status"><b>${answered.correct?'Boa decisão.':'Vamos revisar essa decisão.'}</b><br>${q.feedback}</div><div class="actions"><button class="primary" data-course="next">${lessonState.step===3?'Ver resultado':'Próxima decisão'}</button></div>`:`<button class="primary" data-course="confirm" ${selected===null?'disabled':''}>Confirmar resposta</button>`}`};if(focus)lesson.querySelector('h2').focus()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.choice!==undefined){selected=+b.dataset.choice;drawLesson();lesson.querySelectorAll("[data-choice]")[selected].focus();return}switch(b.dataset.course){case 'start':lessonState.step=0;saveLesson();drawLesson(true);break;case 'confirm':if(selected===null||lessonState.answers[lessonState.step])return;lessonState.answers[lessonState.step]={choice:selected,correct:selected===questions[lessonState.step].answer};saveLesson();drawLesson(true);break;case 'next':lessonState.step++;selected=null;if(lessonState.step===4)lessonState.finished=true;saveLesson();drawLesson(true);break;case 'restart':lessonState={step:0,answers:[],finished:false};selected=null;saveLesson();drawLesson(true);break}});drawLesson();


